div.script:
/*
IMPORTANT:
Replace this with the URL of your own authorized server.

Example:
https://your-server.onrender.com
*/

const PROXY_SERVER = "https://miguelbest.onrender.com";

let history = [];
let historyPosition = -1;

const urlBox = document.getElementById("url");
const home = document.getElementById("home");
const browser = document.getElementById("browser");
const search = document.getElementById("search");
const tabs = document.getElementById("tabs");
const menu = document.getElementById("menu");

function cleanURL(value){

value = value.trim();

if(!value){
return "";
}

if(!/^https?:\/\//i.test(value)){
value = "https://" + value;
}

return value;

}

function go(){

const value = urlBox.value.trim();

if(!value){
return;
}

const target = cleanURL(value);

history = history.slice(0,historyPosition + 1);

history.push(target);

historyPosition++;

load(target);

}

function load(target){

home.style.display = "none";
browser.style.display = "block";

urlBox.value = target;

const proxyURL =
PROXY_SERVER +
"/proxy?url=" +
encodeURIComponent(target);

browser.src = proxyURL;

setTabName(target);

}

function homeGo(){

const value = search.value.trim();

if(!value){
return;
}

urlBox.value = value;

go();

}

function goHome(){

browser.style.display = "none";
home.style.display = "flex";

urlBox.value = "";

setTabName("New Tab");

}

function goBack(){

if(historyPosition <= 0){
return;
}

historyPosition--;

load(history[historyPosition]);

}

function goForward(){

if(historyPosition >= history.length - 1){
return;
}

historyPosition++;

load(history[historyPosition]);

}

function reloadPage(){

if(browser.style.display === "block"){
browser.src = browser.src;
}

}

function fullScreen(){

if(!document.fullscreenElement){

document.documentElement.requestFullscreen?.();

}else{

document.exitFullscreen?.();

}

}

function toggleMenu(){

menu.classList.toggle("show");

}

function createTab(){

goHome();

document
.querySelectorAll(".tab")
.forEach(tab=>{
tab.classList.remove("active");
});

const tab = document.createElement("div");

tab.className = "tab active";

tab.innerHTML =
'<span class="tabtitle">New Tab</span>' +
'<span class="close">×</span>';

tab.querySelector(".close").onclick =
function(event){
closeTab(event);
};

tabs.insertBefore(
tab,
document.getElementById("newtab")
);

}

function closeTab(event){

event.stopPropagation();

const tab =
event.target.closest(".tab");

if(!tab){
return;
}

const all =
document.querySelectorAll(".tab");

if(all.length === 1){
goHome();
return;
}

tab.remove();

const remaining =
document.querySelector(".tab");

if(remaining){
remaining.classList.add("active");
}

}

function setTabName(value){

const active =
document.querySelector(".tab.active");

if(!active){
return;
}

const title =
active.querySelector(".tabtitle");

if(!title){
return;
}

if(value === "New Tab"){
title.textContent = "New Tab";
return;
}

try{

title.textContent =
new URL(value).hostname;

}catch{

title.textContent = "miguelbest";

}

}

document.addEventListener("click",function(event){

if(
!menu.contains(event.target) &&
!event.target.closest("#top button")
){

menu.classList.remove("show");

}

});
